function handle(events,objects=new Map()){
  if(!events.length)return;
  for(const e of events){
    if(e.type==='level-started'){if(e.isTutorial){guideOnce('training-intro',{title:'Ich bin NIM. Wir üben zusammen!',text:'Hier zeigen dir kleine Hilfen, was sinnvoll ist. Außerhalb des Trainings entscheidest du selbst. Während ich spreche, pausiert das Spiel.',animation:'wave'});guideOnce('training-swipe',{title:'Ein Wisch, kein einzelner Tipp',text:'Halte die Maustaste gedrückt und ziehe durch eine Ablenkung. Am Handy: Finger aufsetzen und durchziehen. Folge der Wischspur!',animation:'swipe'});}else guideOnce(game.state.context,{title:contexts[game.state.context]?.name||'Dein nächster Raum',text:`${contexts[game.state.context]?.goal||''} Jetzt gibt es keine Lösungsschilder mehr. Erkenne selbst, was gerade zu deinem Ziel passt.`,animation:'wave'});}
    if(e.type==='sliced'&&game.state.isTutorial)guideOnce('training-keep',{title:'Guter Schnitt! Jetzt bewusst behalten.',text:'Sinnvolle Dinge lässt du unberührt bis über den oberen Rand fliegen. Schneidest du sie oder verpasst eine Ablenkung, kostet das ein Herz. Im Training kannst du in Ruhe weiterüben.',animation:'keep'});
    if(e.type==='tutorial-complete')guideOnce('training-complete',{title:'Bereit für dein Abenteuer!',text:'Du kannst wischen und bewusst durchlassen. Im echten Spiel verschwinden die WISCHEN-/BEHALTEN-Hilfen. Schau auf dein Ziel, sammle Münzen und wachse mit jeder Runde.',animation:'achievement'});
    if(e.type==='coin-earned'&&!game.state.isTutorial)guideOnce('first-coins',{title:'Deine ersten Rundenmünzen!',text:'Gute Entscheidungen, Kombos und goldene Münzen füllen deinen Rundenbeutel. Am Rundenende landen sie sicher im Dojo – auch wenn deine Herzen aufgebraucht sind.',animation:'coins'});
    if(e.type==='powerup')guideOnce('first-powerup',{title:'Ein kleiner Bonus für dich!',text:'Goldene Power-ups darfst du schneiden: Sie geben Zeitlupe, einen Schild, doppelte Punkte oder Münzen. Deine aktive Wirkung siehst du über dem Spielfeld.',animation:'super'});
    if(e.type==='flow-started')guideOnce('first-flow',{title:'Du bist im Focus Flow!',text:'Fünf richtige Entscheidungen am Stück geben dir einen kurzen Flow. Deine Wischspur wird breiter und die Welt feiert mit dir. Bleib bei deinem Ziel!',animation:'super'});
    if(e.type==='super-used')guideOnce('first-super-use',{title:'Super eingesetzt!',text:'Stark! Gute Entscheidungen laden deine Super erneut auf. Im Fähigkeitenbaum kannst du vor deiner nächsten neuen Runde eine andere Super ausrüsten.',animation:'super'});
    const fx={...e,object:e.object||objects.get(e.id)||game.state.objects.find(o=>o.id===e.id)};renderer.effect(fx);audio.play(e);
    if(e.type==='sliced'||e.type==='useful-passed'){if(e.type==='sliced'&&e.combo>0&&e.combo%5===0){reward(`STARK! ${e.combo}er-COMBO`,'combo',1500);audio.play({type:'combo',combo:e.combo})}else reward(e.type==='useful-passed'?`Gut behalten! +${e.points??100}`:`Zack! +${e.points??100}`)}
    if(e.type==='flow-started'){reward('SUPER FLOW! ✦','bonus',1700);audio.play({type:'bonus'})}
    if(e.type==='useful-mistake')toast(e.protected?'Dein Fokus-Schild fängt den Fehler ab.':'Dieses Signal war jetzt sinnvoll. Lass es beim nächsten Mal durch.');
    if(e.type==='distraction-missed')toast(e.protected?'Dein Schild fängt die Ablenkung ab.':'Ablenkung durchgelassen: ein Herz verloren. Entscheide anhand deines aktuellen Ziels.');
    if(e.type==='powerup')reward({slow:'ZEITLUPEN-BONUS! ◷',shield:'SCHILD-BONUS! ♥',multiplier:'DOPPELTE PUNKTE! ★',coins:'MÜNZEN GESAMMELT! ●'}[e.effect||e.powerup||e.power]||'BONUS!','bonus',1700);
    if(e.type==='coin-earned'&&e.amount>=3)reward(`+${e.amount} MÜNZEN! ●`,'combo',1200);
    if(e.type==='super-used')reward(`${skillById(e.id)?.name||'SUPER'}!`,'bonus',1700);
    if(e.type==='achievement-unlocked')toast(`Erfolg: ${ACHIEVEMENTS.find(achievement=>achievement.id===e.id)?.name||e.id}. Münzbelohnung im Erfolgsmenü abholen!`);
    if(e.type==='bonus-phase-start')announce(e.name||game.state.bonusPhase?.name||'Bonusrunde!');
    if(e.type==='second-chance'||e.type==='revived')reward('ZWEITE CHANCE! ♥','bonus',1700);
    if(e.type==='sleep-continued'){reward('BONUS! +200 ★','bonus',1700);renderer.effect({type:'powerup',effect:'multiplier',text:'+200 BONUS!'});audio.play({type:'bonus'})}
    if(e.type==='context-changing')announce('Zimmerwechsel! Gleich geht’s weiter.');
    if(e.type==='context-changed')announce(`Willkommen im ${contexts[game.state.context]?.name||'nächsten Zimmer'}!`);
  }renderHUD();
}
function localPoint(e){const r=$('world').getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top,t:performance.now()/1000}}
function movePointer(e){if(e.pointerId!==swipePointer||!running())return;const p=localPoint(e),before=new Map(game.state.objects.map(o=>[o.id,{...o}]));if(lastPoint)handle(game.swipe([lastPoint,p]),before);lastPoint=p;trail.push(p);if(trail.length>30)trail.shift();renderer.setTrail(trail)}
function wire(){
  $('profile-button').onclick=playerMenu;if($('notifications-button'))$('notifications-button').onclick=notifications;
  $('player-overview')?.addEventListener('click',e=>{const action=e.target.closest('[data-overview-action]')?.dataset.overviewAction;if(action==='achievements')achievementMenu();else if(action==='abilities')abilities()});
  $('overlay-root').addEventListener('submit',e=>{if(e.target.id!=='username-form')return;e.preventDefault();const result=game.setUsername($('username-input').value);if(!good(result)){$('username-error').textContent=why(result);$('username-input').setAttribute('aria-invalid','true');return;}overviewToken='';save();if(ui==='onboarding'){showHome();guideOnce('welcome',{title:`Hey ${game.profile.player.username}, willkommen!`,text:'Ich bin NIM und begleite dich. Starte mit dem Training: Dort üben wir Wischen und bewusstes Durchlassen. In deinem Dojo findest du Münzen, Level, neue Räume und deine Kräfte.',animation:'wave',buttonLabel:'Zeig mir mein Dojo!'});}else{playerMenu();toast('Ninja-Name gespeichert.')}renderHUD();});
  $('launch').onclick=launch;$('continue').onclick=continueRun;$('pause-button').onclick=pause;$('sound-toggle').onclick=toggleSound;$('help-button').onclick=help;$('skins-button').onclick=()=>shop();$('highscores-button').onclick=highscores;$('stop-button').onclick=sleepChoice;$('skills-button').onclick=abilities;$('achievements-button').onclick=achievementMenu;$('super-button').onclick=activateSuper;$('shop-button').onclick=()=>shop();$('training-button').onclick=launchTraining;
  $('world-map').addEventListener('click',event=>{const target=event.target.closest('button');if(!target||target.disabled)return;if(target.dataset.worldBuy)purchaseWorld(target.dataset.worldBuy);else if(target.dataset.worldPlay)playWorld(target.dataset.worldPlay)});
  $('world').addEventListener('pointerdown',e=>{if(!running()||swipePointer!==null||e.button!==0)return;e.preventDefault();swipePointer=e.pointerId;lastPoint=localPoint(e);trail=[lastPoint];$('world').setPointerCapture(e.pointerId);renderer.setTrail(trail)});
  $('world').addEventListener('pointermove',e=>{if(e.pointerId!==swipePointer)return;e.preventDefault();const samples=e.getCoalescedEvents?.();for(const p of samples?.length?samples:[e])movePointer(p)});
  $('world').addEventListener('pointerup',e=>{movePointer(e);if(e.pointerId===swipePointer){swipePointer=null;lastPoint=null}});$('world').addEventListener('pointercancel',()=>{swipePointer=null;lastPoint=null});
  $('overlay-root').addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const action=b.dataset.action;if(b.dataset.skillInspect){selectedSkill=b.dataset.skillInspect;abilities();$('overlay-root').querySelector('.skill-detail')?.scrollIntoView({block:'nearest',behavior:'smooth'});return;}if(b.dataset.treeBranch){const skill=SKILLS.find(s=>s.branch===b.dataset.treeBranch&&!game.profile.unlockedSkills.includes(s.id))||SKILLS.find(s=>s.branch===b.dataset.treeBranch);selectedSkill=skill.id;abilities();const node=$('overlay-root').querySelector(`[data-skill-inspect="${skill.id}"]`);node?.scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'});return;}if(b.dataset.unlockView){const type=b.dataset.unlockView;if(type==='skill'){selectedSkill=b.dataset.unlockRef;abilities();$('overlay-root').querySelector('.skill-detail')?.scrollIntoView({block:'nearest'});}else if(type==='achievement'){achievementMenu();$('overlay-root').querySelector(`[data-achievement="${b.dataset.unlockRef}"]`)?.scrollIntoView({block:'nearest'});}else if(type==='level')playerMenu();else shop(type==='world'?'worlds':type==='skin'?'skins':'backgrounds');return;}if(b.dataset.skin){const id=b.dataset.skin,owned=game.profile.unlockedSkins.includes(id);const r=owned?game.selectSkin(id):game.buySkin(id);if(!good(r))toast(why(r));else if(!owned)game.selectSkin(id);skins();renderHUD();save();return;}
    if(b.dataset.shopTab){shop(b.dataset.shopTab);return;}
    if(b.dataset.worldBuy){purchaseWorld(b.dataset.worldBuy);return;}
    if(b.dataset.worldPlay){playWorld(b.dataset.worldPlay);return;}
    if(b.dataset.backgroundBuy){const result=game.buyBackground(b.dataset.backgroundBuy);if(!good(result))toast(why(result));else{audio.play({type:'skill-unlocked'});toast('Neue Kulisse gekauft. Wähle sie jetzt für deinen Raum aus.')}shop('backgrounds');save();return;}
    if(b.dataset.backgroundEquip){const result=game.selectBackground(b.dataset.backgroundEquip);if(!good(result))toast(why(result));else toast('Kulisse ausgewählt. Aktiv ab deiner nächsten neuen Runde.');mapToken='';shop('backgrounds');save();return;}
    if(b.dataset.skillBuy){const result=game.buySkill(b.dataset.skillBuy);if(!good(result))toast(why(result));else{handle(result.events||[]);audio.play({type:'skill-unlocked'});toast('Fähigkeit freigeschaltet. Aktiv ab deiner nächsten neuen Runde.')}abilities();save();return;}
    if(b.dataset.superEquip){const result=game.selectSuper(b.dataset.superEquip);if(!good(result))toast(why(result));else toast('Super ausgerüstet. Aktiv ab deiner nächsten neuen Runde.');abilities();save();return;}
    if(b.dataset.achievementClaim){const result=game.claimAchievement(b.dataset.achievementClaim);if(!good(result))toast(why(result));else{handle(result.events||[]);audio.play({type:'coin-earned'});toast(`+${result.reward||0} Münzen abgeholt!`);guideOnce('first-reward',{title:'Belohnung gesichert!',text:'Diese Münzen sind jetzt in deinem Dojo. Jede Erfolgsbelohnung lässt sich einmal abholen. Schau im Wurzelbaum oder Basar, was als Nächstes zu dir passt.',animation:'coins'})}achievementMenu();save();return;}
    if(action==='next')next();else if(action==='skip-tutorial'){const r=game.skipTutorial();if(good(r)){ui='briefing';lastCoreToken='';sync()}else toast(why(r));}else if(action==='resume')resume();else if(action==='home')showHome();else if(action==='close-menu')closeMenu();else if(action==='stop')stop();else if(action==='extend')extend();else if(action==='sleep-bonus')sleepBonus();else if(action==='again')launch();else if(action==='training')launchTraining();else if(action==='skins')skins();else if(action==='shop')shop();else if(action==='abilities')abilities();else if(action==='achievements')achievementMenu();else if(action==='export')exportData();else if(action==='profile')playerMenu();else if(action==='notifications')notifications();else if(action==='read-notifications'){game.markNotificationsRead();notifications();save();}
  });
  window.addEventListener('keydown',e=>{if(mentor?.isOpen()||ui==='onboarding')return;if(e.target instanceof HTMLSelectElement||e.target instanceof HTMLInputElement)return;if(e.code==='Space'&&running()&&!e.repeat&&!(e.target instanceof HTMLButtonElement)){e.preventDefault();activateSuper()}if(e.key==='Escape'){e.preventDefault();if(ui==='paused')resume();else if(running())pause();else if(menuKinds.includes(ui))closeMenu()}if(e.key.toLowerCase()==='m'&&!e.repeat)toggleSound()});
  window.addEventListener('blur',()=>{if(running())pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&running())pause()});window.addEventListener('pagehide',save);
  const resizeGame=()=>{renderer.resize();const size=renderer.getSize();game.resize(size.width,size.height)};if('ResizeObserver'in window)new ResizeObserver(resizeGame).observe($('arena'));else window.addEventListener('resize',resizeGame);
}
function frame(t){
  const dt=Math.min(.05,Math.max(0,(t-lastTime)/1000));lastTime=t;
  if(running()){const before=new Map(game.state.objects.map(o=>[o.id,{...o}]));handle(game.update(dt),before);sync();saveClock+=dt;if(saveClock>=2){saveClock=0;save()}
    const s=game.state,token=`${s.startedAt}:${s.stageIndex}`;if(s.context==='sleep'&&s.levelIndex===2&&s.stopAvailable&&sleepOfferToken!==token){sleepOfferToken=token;sleepChoice()}
  }
  sync();
  renderer.render({...game.state,backgrounds:ui==='home'?game.profile.selectedBackgrounds:game.state.backgrounds,skinData:skinList().find(s=>s.id===game.state.skin),scene:ui==='home'?'home':game.state.scene,paused:ui!=='playing'||game.state.paused,training:game.state.isTutorial},t/1000);audio.update({...game.state,paused:ui!=='playing'||game.state.paused},dt);
  hudClock+=dt;if(hudClock>.1){hudClock=0;renderHUD()}requestAnimationFrame(frame)
}
function boot(){
  try{renderer=createRenderer($('world'));audio=createAudio();try{sound=localStorage.getItem('notification-ninja:music')!=='false'}catch{}audio.setEnabled(sound);updateSoundUI();const size=renderer.getSize();game=new NinjaGame({width:size.width,height:size.height});knownUnlocks=currentUnlocks();knownLevel=getPlayerProgress(game.profile).level;mentor=createMentor({root:$('mentor-root'),onOpen:()=>{mentorResume=ui==='playing'&&game.state.scene==='playing'&&!game.state.paused;game.pause();swipePointer=null;lastPoint=null;trail=[];renderer.setTrail(trail);},onClose:()=>{if(mentorResume&&ui==='playing'&&game.state.scene==='playing'){if(document.hidden)pauseDialog();else game.resume();}mentorResume=false;renderHUD();}});if(game.state.started){$('difficulty-select').value=game.state.difficulty||'easy';$('mode-select').value=game.state.mode;$('gaming-limit').value=String(game.state.gamingLimit||60)}wire();showHome();if(game.profile.player.username)guideOnce('welcome',{title:`Willkommen, ${game.profile.player.username}!`,text:'Ich bin NIM. Im Training zeige ich dir das Wischen und bewusste Durchlassen. Dein Dojo sammelt Münzen, Level und neue Kräfte.',animation:'wave'});$('loading').hidden=true;requestAnimationFrame(frame);
    window.__NOTIFICATION_NINJA__=Object.freeze({getSnapshot:()=>({version:'1.3.0',ui,mentor:mentor.getStats(),playerProgress:getPlayerProgress(game.profile),state:JSON.parse(JSON.stringify(game.state)),profile:JSON.parse(JSON.stringify(game.profile)),renderer:renderer.getStats(),audio:audio.getStats(),musicEnabled:sound,storageFailed:game.storageFailed})});
    if(location.protocol==='file:'){$('download').hidden=true;document.querySelectorAll('.project-link').forEach(link=>link.hidden=true)}
    if(location.protocol.startsWith('http')&&'serviceWorker'in navigator){const controlled=Boolean(navigator.serviceWorker.controller);let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(controlled&&!reloading){reloading=true;save();location.reload()}});navigator.serviceWorker.register('./sw.js').catch(()=>{})}
  }catch(error){console.error('Notification Ninja startup failed',error);$('loading').hidden=true;dialog('Die Klinge konnte nicht starten.',`<p class="muted">${escape(error.message)}</p>`,button('Neu laden','reload'));$('overlay-root').querySelector('button').onclick=()=>location.reload()}
}
